#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""Wrap a vendored FM-1 firmware emulator as two classic scripts a file:// page can <script src>.

Chrome blocks fetch() / XHR / module imports of file:// URLs, so the tools cannot load a .wasm or
addModule() a worklet from disk. Instead each build becomes:

  <id>/<id>_wasm.js     window.FM1EMU['<id>'].wasmB64     (the .wasm, base64)
  <id>/<id>_worklet.js  window.FM1EMU['<id>'].workletSrc  (the upstream worklet.js text, verbatim)

fm1_emu.js decodes the first and addModule()s the second as a data: URL (on file:// Chrome
refuses Blob-URL worklet modules: their origin is null).

  python3 -I pack.py ID                    re-wrap from the files already in vendor/fm1emu/ID/
  python3 -I pack.py ID --from DIR         copy DIR's upstream wasm + worklet.js in first (an update), then wrap
  python3 -I pack.py all                   re-wrap every known ID

ID is one of the BUILDS below. --wasm FILE / --worklet FILE override the inputs (used when DIR names
them differently). Python 3 standard library only.
"""
import argparse
import base64
import hashlib
import json
import shutil
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent

# wasm: the file wrapped into <id>_wasm.js. upstream: the names an upstream emulator directory uses
# (gh-pages webapp/try/ for Felucca, emu/ for X0X), copied in by --from.
BUILDS = {
    "felucca": {"wasm": "felucca.wasm", "upstream_wasm": "felucca.wasm", "worklet": "worklet.js"},
    # X0X's upstream web build has no MIDI input; x0x_midi.wasm is that build plus x0x_web_midi.patch
    # (build_midi.sh). --from refreshes the upstream originals; rebuild x0x_midi.wasm, then pack again.
    "x0x": {"wasm": "x0x_midi.wasm", "upstream_wasm": "x0x.wasm", "worklet": "worklet.js"},
}


def js_assign(id_, fields):
    body = ", ".join(f"{k}: {json.dumps(v, ensure_ascii=True)}" for k, v in fields.items())
    return (f"/* generated by vendor/fm1emu/pack.py - do not edit; GPL-3.0-only, see LICENSE and SOURCE.md here */\n"
            f"(window.FM1EMU = window.FM1EMU || {{}})[{json.dumps(id_)}] = "
            f"Object.assign(window.FM1EMU[{json.dumps(id_)}] || {{}}, {{ {body} }});\n")


def pack(id_, src=None, wasm=None, worklet=None):
    cfg = BUILDS[id_]
    out = HERE / id_
    out.mkdir(exist_ok=True)
    if src:
        src = Path(src)
        for a, b in ((wasm or src / cfg["upstream_wasm"], out / cfg["upstream_wasm"]),
                     (worklet or src / cfg["worklet"], out / cfg["worklet"])):
            if Path(a).resolve() != b.resolve():
                shutil.copyfile(a, b)
                print(f"copied {a} -> {b}")
        wasm = worklet = None
    wasm_path = Path(wasm) if wasm else out / cfg["wasm"]
    worklet_path = Path(worklet) if worklet else out / cfg["worklet"]
    wb = wasm_path.read_bytes()
    if wb[:4] != b"\0asm":
        raise SystemExit(f"{wasm_path}: not a WebAssembly module")
    src_text = worklet_path.read_text(encoding="utf-8")
    if "registerProcessor" not in src_text:
        raise SystemExit(f"{worklet_path}: no registerProcessor (not an AudioWorklet module?)")
    sha = hashlib.sha256(wb).hexdigest()
    (out / f"{id_}_wasm.js").write_text(js_assign(id_, {
        "wasmFile": wasm_path.name, "wasmBytes": len(wb), "wasmSha256": sha,
        "wasmB64": base64.b64encode(wb).decode("ascii")}), encoding="ascii")
    (out / f"{id_}_worklet.js").write_text(js_assign(id_, {
        "workletFile": worklet_path.name,
        "workletSha256": hashlib.sha256(src_text.encode("utf-8")).hexdigest(),
        "workletSrc": src_text}), encoding="ascii")
    print(f"{id_}: {wasm_path.name} {len(wb)} B (sha256 {sha[:16]}…), {worklet_path.name} {len(src_text)} chars"
          f" -> {id_}_wasm.js, {id_}_worklet.js")


def main(argv):
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("id", choices=sorted(BUILDS) + ["all"])
    ap.add_argument("--from", dest="src", help="an upstream emulator directory to copy the originals from")
    ap.add_argument("--wasm", help="the .wasm to wrap (default: per BUILDS)")
    ap.add_argument("--worklet", help="the worklet.js to wrap (default: worklet.js)")
    a = ap.parse_args(argv)
    for id_ in (sorted(BUILDS) if a.id == "all" else [a.id]):
        pack(id_, a.src, a.wasm, a.worklet)


if __name__ == "__main__":
    main(sys.argv[1:])
